SourceCode.Declaration:
/// <summary>
/// The recurring batch job that registers and posts what handhelds have staged: every
/// [recurrenceMinutes] it starts one task (HSMobileOpsPostingWorker) for each warehouse with
/// Pending rows in HSMobileOpsPostQueue, in every company. Without it a receipt queued on a
/// handheld - offline, or by a worker who signs out before opening Activity - stays Pending, and
/// big postings are never worked at all.
///
/// How many run at once is the batch server's setting: its threads, in its batch group. Tasks
/// beyond that wait their turn, and the job's next run waits for all of them.
///
/// One job per environment, created by [ensureScheduled]: the first press of "Process pending",
/// or on purpose from ?mi=SysClassRunner&amp;cls=HSMobileOpsProcessPendingBatch. Withholding or
/// changing it under System administration > Batch jobs is respected - only a job that is gone
/// (deleted, cancelled, finished) is created again.
/// </summary>
class HSMobileOpsProcessPendingBatch extends RunBaseBatch
{
    #define.CurrentVersion(1)
}

Method.Source:
/// <summary>
/// Schedules the recurring job if it does not exist yet, and says which it was.
/// </summary>
public static void main(Args _args)
{
    if (HSMobileOpsProcessPendingBatch::ensureScheduled())
    {
        info(strFmt('Batch job "%1" scheduled: every %2 minutes.',
            HSMobileOpsProcessPendingBatch::caption(), HSMobileOpsProcessPendingBatch::recurrenceMinutes()));
    }
    else
    {
        info(strFmt('Batch job "%1" is already scheduled - see System administration > Batch jobs.',
            HSMobileOpsProcessPendingBatch::caption()));
    }
}

public static str caption()
{
    return 'Mobile ops: process pending postings';
}

/// <summary>
/// Whether a job running this class still exists and has not ended - waiting, executing,
/// withheld or in error all count, so a job someone has paused is not doubled.
/// </summary>
public static boolean isScheduled()
{
    Batch    batch;
    BatchJob batchJob;

    select firstOnly RecId from batch
        where batch.ClassNumber == classNum(HSMobileOpsProcessPendingBatch)
        exists join batchJob
            where batchJob.RecId  == batch.BatchJobId
               && batchJob.Status != BatchStatus::Canceled
               && batchJob.Status != BatchStatus::Finished;

    return batch.RecId != 0;
}

/// <summary>
/// Creates the recurring job - every [recurrenceMinutes], no end date, starting now - unless
/// one exists. Returns true when this call created it.
/// </summary>
public static boolean ensureScheduled()
{
    BatchHeader       batchHeader;
    SysRecurrenceData recurrence;

    if (HSMobileOpsProcessPendingBatch::isScheduled())
    {
        return false;
    }

    recurrence = SysRecurrence::defaultRecurrence();
    recurrence = SysRecurrence::setRecurrenceStartDateTime(recurrence, DateTimeUtil::utcNow());
    recurrence = SysRecurrence::setRecurrenceNoEnd(recurrence);
    recurrence = SysRecurrence::setRecurrenceUnit(recurrence, SysRecurrenceUnit::Minute,
        HSMobileOpsProcessPendingBatch::recurrenceMinutes());

    batchHeader = BatchHeader::construct();
    batchHeader.parmCaption(HSMobileOpsProcessPendingBatch::caption());
    batchHeader.parmRecurrenceData(recurrence);
    batchHeader.addTask(new HSMobileOpsProcessPendingBatch());
    batchHeader.save();

    return true;
}

/// <summary>
/// Rows left Processing by a run that died part way are failed for a person to check
/// (HSMobileOpsPostQueue::failInterrupted), then every warehouse with Pending rows gets a task.
/// Outside batch, with no tasks to add to, the warehouses are simply worked in turn.
/// </summary>
public void run()
{
    HSMobileOpsPostQueue postQueue;
    BatchHeader          batchHeader;
    boolean              added;

    while select crossCompany DataAreaId from postQueue
        group by DataAreaId
        where postQueue.Status == HSMobileOpsPostQueue::statusProcessing()
    {
        HSMobileOpsPostingService::failInterruptedIn(postQueue.DataAreaId);
    }

    if (this.isInBatch())
    {
        batchHeader = BatchHeader::construct(this.parmCurrentBatch().BatchJobId);
    }

    while select crossCompany DataAreaId, Warehouse from postQueue
        group by DataAreaId, Warehouse
        where postQueue.Status == HSMobileOpsPostQueue::statusPending()
    {
        if (batchHeader)
        {
            batchHeader.addRuntimeTask(
                HSMobileOpsPostingWorker::newTask(postQueue.DataAreaId, postQueue.Warehouse),
                this.parmCurrentBatch().RecId);
            added = true;
        }
        else
        {
            HSMobileOpsPostingService::processWarehouse(postQueue.DataAreaId, postQueue.Warehouse);
        }
    }

    if (added)
    {
        batchHeader.save();
    }
}
